export const getProductConfiguration = (page = 1, pageSize = 10, payload = {}) => {
  return async (dispatch) => {
    dispatch(productconfigBegin());

    try {
      const finalPayload = {
        ...payload,
        pagination: {
          page,
          page_size: pageSize,
        },
      };
      const response = await DataService.post(`/amazon/channel-product-config-items/`, finalPayload);

      if (response.data.status === true) {
        dispatch(productconfigSuccess(response.data));
      } else {
        dispatch(productconfigErr('Something went wrong'));
      }
    } catch (err) {
      dispatch(productconfigErr(err.message));
    }
  };
};

export const exportProductConfiguration = (channels = [], search = '') => {
  return async (dispatch) => {
    dispatch(exportproductconfigurationBegin());

    try {
      const channelQuery = Array.isArray(channels) ? channels.join(',') : channels || '';
      const params = new URLSearchParams();
      if (channelQuery) params.append('channels', channelQuery);
      if (search) params.append('search', search);

      const queryString = params.toString();
      const url = `/amazon/export-channel-product-config-excel/${queryString ? `?${queryString}` : ''}`;
      const response = await DataService.get(url);

      console.log('Export Response:', response.data);

      if (response.data.status && response.data.download_url) {
        window.open(response.data.download_url, '_blank');
        dispatch(exportproductconfigurationSuccess(response.data));
      } else {
        throw new Error('Download URL not found');
      }
    } catch (err) {
      console.log(err);
      dispatch(exportproductconfigurationErr(err.message));
    }
  };
};

export const uploadProductConfiguration = (file) => {
  return async (dispatch) => {
    dispatch(uploadproductconfigurationBegin());

    try {
      const formData = new FormData();
      formData.append('file', file);

      const response = await DataService.post('/amazon/upload-channel-product-config-excel/', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      if (response.data?.status === true) {
        dispatch(uploadproductconfigurationSuccess(response.data));
      } else {
        dispatch(uploadproductconfigurationErr('Something went wrong'));
      }

      return response.data;
    } catch (err) {
      dispatch(uploadproductconfigurationErr(err.message));
      throw err;
    }
  };
};

export const updateProductConfiguration = (payload) => {
  return async () => {
    const response = await DataService.post('/amazon/update-channel-product-config-item/', payload);

    return response.data;
  };
};
